Map<String, Object?>? encBoxShadow(BoxShadow? v) => v == null
    ? null
    : {
        'color': niceEncColor(v.color),
        'offset': encOffset(v.offset),
        'blurRadius': fuseNum(v.blurRadius),
        'spreadRadius': fuseNum(v.spreadRadius),
        'blurStyle': v.blurStyle.name,
      };

Map<String, Object?>? encOffset(Offset? v) => v == null
    ? null
    : {
        'dx': fuseNum(v.dx),
        'dy': fuseNum(v.dy),
      };

Map<String, Object?>? encRadius(Radius? v) => v == null
    ? null
    : {
        'x': fuseNum(v.x),
        'y': fuseNum(v.y),
      };

Map<String, Object?>? encRouteSettings(RouteSettings? v) => v == null
    ? null
    : {
        'name': v.name,
        'arguments': v.arguments,
      };

Map<String, Object?>? encSimulation(Simulation? v) => v == null
    ? null
    : {
        'tolerance': encTolerance(v.tolerance),
      };

Map<String, Object?>? encSystemUiOverlayStyle(services.SystemUiOverlayStyle? v) => v == null
    ? null
    : {
        'systemNavigationBarColor': niceEncColor(v.systemNavigationBarColor),
        'systemNavigationBarDividerColor': niceEncColor(v.systemNavigationBarDividerColor),
        'systemNavigationBarIconBrightness': v.systemNavigationBarIconBrightness?.name,
        'systemNavigationBarContrastEnforced': v.systemNavigationBarContrastEnforced,
        'statusBarColor': niceEncColor(v.statusBarColor),
        'statusBarBrightness': v.statusBarBrightness?.name,
        'statusBarIconBrightness': v.statusBarIconBrightness?.name,
        'systemStatusBarContrastEnforced': v.systemStatusBarContrastEnforced,
      };

Map<String, Object?>? encTolerance(Tolerance? v) => v == null
    ? null
    : {
        'distance': fuseNum(v.distance),
        'time': fuseNum(v.time),
        'velocity': fuseNum(v.velocity),
      };

